"""Real UI: select/filter a GPS trace, explicitly save, separately confirm compaction and delete."""
import argparse
from browser_realtime import check_pages
from check_manual_route_ui import ASSETS as BASE
from check_work_report_layout import STATIC
ASSETS=['map-gestures.js','gps-route-tools.js',*BASE]
def fixture():
    css='\n'.join((STATIC/name).read_text() for name in ['tf-portal.css','work-report.css','responsive.css','portal-theme.css'])
    checks=r'''
(async()=>{
 const assert=(v,m)=>{if(!v)throw Error(m);},wait=ms=>new Promise(r=>setTimeout(r,ms)),until=async fn=>{const end=performance.now()+8000;while(!fn()){if(performance.now()>end)throw Error('Timed out');await wait(20);}};
 window.I18n={t:s=>s};let rows=[],writes=[],confirmAnswer=true,confirms=0,dirty=false,original=true,allowCheck=true,cleanup=[],choices=[],removed=[];window.confirm=()=>{confirms++;return confirmAnswer;};window.AndroidPortal={gps:async method=>{if(method==='archiveInfo')return {running:false,count:2,last:1795165210000};if(method==='erase'){cleanup.push('native');return {};}throw Error(method);}};MapGestures.tiles=()=>{};
 window.GpsRecorder={localRecord:async()=>({dirty,ended:true,revision:3}),removeLocal:async()=>cleanup.push('local'),activeFor:()=>false};
 const a=M1Map.points().byCode.get('AFW')[0],b=M1Map.points().byCode.get('AFR')[0],id='10000000-0000-4000-8000-000000000001';choices=[{journey_id:id,revision:3,sha256:'a'.repeat(64),point_count:2,train_number:'GPS-TEST',ended:true,start:1795165200000,end:1795165210000,from_code:'AFW',to_code:'AFR',lines:[[[a.lat,a.lon,1795165200000],[b.lat,b.lon,1795165210000]]]}];
 window.fetch=async(path,o={})=>{const method=o.method||'GET';if(method==='GET'&&String(path).includes('gps-compaction'))return new Response(JSON.stringify(allowCheck?{owner_id:1,eligible:true,source_gps:choices[0]}:{detail:'GPS coverage is incomplete'}),{status:allowCheck?200:409});if(method==='GET')return new Response(JSON.stringify({owner_id:1,items:rows}));writes.push([path,method,o.body]);if(method==='DELETE'){rows=[];}else if(String(path).endsWith('gps-compaction')){assert(JSON.parse(o.body).confirmed,'Separate explicit consent reaches server');assert(cleanup.join(',')==='native,local','Local originals are cleaned only after verified server copy');original=false;rows[0]={...rows[0],revision:'c'.repeat(64),source_gps:{...rows[0].source_gps,points_removed:true}};}else{const body=JSON.parse(o.body);assert(body.source_gps.journey_id===id,'Saved route binds the selected GPS snapshot');rows=[{id:1,revision:'b'.repeat(64),from_code:body.waypoints[0],to_code:body.waypoints.at(-1),waypoints:body.waypoints,routes:body.routes,valid_until:body.valid_until,source_gps:{...choices[0],points_removed:false}}];}return new Response(JSON.stringify({owner_id:1,items:[],saved_routes:rows}));};
 const root=document.getElementById('root'),editor=ManualRouteEditor.mount({id:1},root,async()=>{},{gpsChoices:()=>choices,gpsRefresh:async row=>{await wait(30);return row;},gpsRemoved:id=>{removed.push(id);choices=[];},drawInventory:(host,make)=>{const p=make('path');p.setAttribute('data-imported-knowledge','qualified');host.append(p);}});await until(()=>!root.querySelector('[data-route-start]').disabled);await wait(60);
 const select=root.querySelector('[data-gps-route-tools] select');assert(select.options.length===2,'Owned finished GPS recording is offered');select.value=id;select.dispatchEvent(new Event('change'));await until(()=>root.querySelector('[data-selected-gps-trace]'));assert(editor.waypoints[0]==='AFW','Known start station is selected for review');editor.select(b);await until(()=>root.querySelector('[data-manual-route-line]'));
 const before=editor.waypoints.join(','),only=root.querySelector('.route-map-gps-only input');only.checked=true;only.dispatchEvent(new Event('change'));await wait(80);assert(!root.querySelector('[data-imported-knowledge]')&&root.querySelector('[data-selected-gps-trace]'),'Filter hides other knowledge, retaining the selected GPS trace');assert(editor.waypoints.join(',')===before&&root.querySelector('[data-manual-route-line]'),'Filtering never removes the new selection');
 assert(writes.length===0&&original,'GPS selection has not saved or removed anything');await root.querySelector('form').onsubmit({preventDefault(){}});await until(()=>root.querySelector('[data-route-compact]'));assert(original&&cleanup.length===0,'Saving the route never deletes the original');select.value=id;select.dispatchEvent(new Event('change'));root.querySelector('[data-saved-route]').click();await wait(70);assert(select.value==='','Loading a saved route cancels an in-flight GPS selection');
 confirmAnswer=false;await root.querySelector('[data-route-compact]').onclick({stopPropagation(){}});assert(original&&cleanup.length===0,'Refusing the second confirmation retains all originals');
 confirmAnswer=true;dirty=true;const count=confirms;await root.querySelector('[data-route-compact]').onclick({stopPropagation(){}});assert(original&&cleanup.length===0&&confirms===count,'Unsent local changes block cleanup before consent');dirty=false;
 allowCheck=false;await root.querySelector('[data-route-compact]').onclick({stopPropagation(){}});assert(original&&cleanup.length===0,'Rejected coverage check never removes local data');allowCheck=true;
 await root.querySelector('[data-route-compact]').onclick({stopPropagation(){}});await until(()=>!root.querySelector('[data-route-compact]'));assert(!original&&removed[0]===id&&rows.length===1,'Explicit compaction retains the compact saved route and removes only selected GPS source');
 confirmAnswer=false;await root.querySelector('[data-route-delete]').onclick({stopPropagation(){}});assert(rows.length===1,'Cancelling manual deletion preserves the route');confirmAnswer=true;await root.querySelector('[data-route-delete]').onclick({stopPropagation(){}});await until(()=>!root.querySelector('[data-saved-route]'));assert(rows.length===0,'Explicit own-route deletion updates the saved list');
 parent.postMessage({layoutStatus:'pass'},'*');
})().catch(error=>parent.postMessage({layoutStatus:'fail',message:error.stack},'*'));
'''
