    p=argparse.ArgumentParser();p.add_argument('--output-dir',required=True);a=p.parse_args();check_pages(fixture,a.output_dir,widths=(800,375),assets={'/tf/'+name:STATIC/name for name in ASSETS},label='Owned GPS-to-route transfer and deletion',timeout=30)
